import React from 'react';

const stats = [
  { icon: '📷', label: 'Cameras',          value: '4 / 6',   sub: 'Online',                  subColor: '#3b82f6' },
  { icon: '🔍', label: 'Total Detections', value: '128',     sub: 'Today',                   subColor: '#64748b' },
  { icon: '🚨', label: 'Active Alerts',    value: '3',       sub: 'View All',                subColor: '#ef4444', valColor: '#ef4444' },
  { icon: '💚', label: 'System Status',    value: 'Healthy', sub: 'All Systems Operational', subColor: '#64748b', valColor: '#22c55e' },
];

export default function StatsRow() {
  return (
    <div style={{
      display: 'grid', gridTemplateColumns: 'repeat(4,1fr)',
      borderBottom: '1px solid #1e2d47', flexShrink: 0,
      gap: '1px', background: '#1e2d47'
    }}>
      {stats.map((s, i) => (
        <div key={i} style={{
          background: '#111827', padding: '10px 14px',
          display: 'flex', alignItems: 'center', gap: 12
        }}>
          <span style={{ fontSize: 24 }}>{s.icon}</span>
          <div>
            <div style={{ fontSize: 10, color: '#64748b' }}>{s.label}</div>
            <div style={{ fontSize: 20, fontWeight: 700, color: s.valColor || '#fff', lineHeight: 1.1 }}>{s.value}</div>
            <div style={{ fontSize: 10, color: s.subColor, marginTop: 2 }}>{s.sub}</div>
          </div>
        </div>
      ))}
    </div>
  );
}
